    parts.append('<div class="grp"><p>%s</p><div>%s</div></div>' % (e(label), "".join(
        '%s<span class="t">%s</span>' % (chip(n), e(short(n))) for n in ns)))
parts.append("</section>")

parts.append('<section id="tonight"><h2>I finish tonight <i>%d rows · about 30 min all in · no calls needed</i></h2><div class="cards">' % len(TONIGHT))
for n, st, why, rec, eta in TONIGHT:
    parts.append('<article class="card go"><div class="top">%s<b>%s</b><span class="state">%s</span></div><p>%s</p>'
                 '<div class="rec"><span>REC</span><em>%s</em><span class="eta">%s</span></div></article>' % (chip(n), e(short(n)), e(st), e(why), e(rec), e(eta)))
parts.append("</div></section>")

parts.append('<section id="calls"><h2>One word from you <i>%d rows · each closes or unblocks on your call</i></h2><div class="cards">' % len(CALLS))
for n, q, why, rec in CALLS:
    parts.append('<article class="card call"><div class="top">%s<b>%s</b></div><p>%s</p>'
                 '<div class="rec"><span>REC</span><em>%s</em></div></article>' % (chip(n), e(q), e(why), e(rec)))
parts.append("</div></section>")

parts.append('<section id="long"><h2>Long haul <i>%d rows · real builds, weeks not hours</i></h2>'
             '<p class="lede">These are open for good reason: whole systems, the fabula, the courses, the 90-day plan. None of them finishes this week.</p><div class="long">' % len(LONG))
parts.append("".join('<span class="it">%s%s</span>' % (chip(n), e(short(n))) for n in sorted(LONG)))
parts.append("</div></section>")

parts.append('<footer>Not shown: %d rows in storage (COSMOLINE, out of the rotation since 10/13)%s. '
             'Source: BOLO.md, read 11/04. Recs are mine; nothing changes until you say go.</footer>' % (
                 len(cosmo), (" · unsorted: " + ", ".join(map(str, sorted(missing)))) if missing else ""))
parts.append("</main>")
io.open(SP + "docket/the-docket.html", "w", encoding="utf-8").write("\n".join(parts))
print("stamp", n_stamp, "tonight", len(TONIGHT), "calls", len(CALLS), "long", len(LONG), "cosmo", len(cosmo), "missing", missing)

