"""The docket v2 (11/04): every open BOLO, clickable. Picks go to the db doc orders/latest; Claude reads them.
Every active row lands in exactly one lane or the build stops."""
import html, io, json, re, sys

SP = "C:/Users/U01_LE~1/AppData/Local/Temp/claude/162b4a1b56362423/33907b68-3f24-4eee-a1e5-bc0f315e2139/scratchpad/"
A = {int(k): v for k, v in json.load(io.open(SP + "active.json", encoding="utf-8")).items()}
e = lambda s: html.escape(str(s), quote=True)


def short(n):
    t = re.split(r" \[| — | - |: ", A[n]["title"])[0].strip()
    return t[:72]


# lane: stamp = done, I close it · do = I finish it, no call needed · call = your word · long = real build · cosmo = storage
STAMP = [
    (84, "Closed 9/29 (no Prime Air, no reason for the certificate); the row never moved."),
