    (111, "Built 10/6 and in use: the log, the calendar and JUDY's \"log it\"."),
    (115, "Built 10/6 and in service on the Console."),
    (140, "Built 10/12: the intake skill runs on \"intake\" plus links."),
    (141, "Live v3 10/31: the desk is on the shared theme and served by the Console."),
]
