    (150, "Anna's domain: Manipulation or Fixed Attitude?", "The last open call on the story export.", "Fixed Attitude (the newer 9/23 line)."),
    (22, "The Atlanta recommendation: take it?", "Recon delivered 9/1; only your ruling is left.", "Take the rec, then close."),
    (170, "Scan sorter bins: use the six intake bins?", "Nothing moves until the typewriter pages have a home.", "Use the six default bins."),
    (98, "ORANGE board: go, and where do the two private threads live?", "Built 10/4; waiting on the go and a home for two threads.", "Go; both threads live in your private folder."),
    (148, "The Bearings: drop the poster PDF.", "The zip held only print instructions.", "You drop the PDF, I map it."),
    (172, "ORANGE catalog: rule the first split.", "Given in chat 10/30; the detail waits on it.", "Take the split as given."),
    (99, "The advice voice: name and voice.", "Sat to burn on 10/4.", "Luna, with the voice changer."),
    (160, "Claude's eyes: install agent-browser?", "Queued 10/19; first job checks the Console's screens.", "Go (install on your word)."),
    (151, "The pager trial: start it?", "Sandboxed, one job: text you when a pull stalls.", "Hold until the pull finishes."),
    (143, "The clean tree: run stage 1?", "60+ root entries; stage 1 is a dry run first.", "Go stage 1 (dry run only)."),
    (125, "The review desk: build it?", "Most of it exists already; build on go.", "Go."),
    (119, "Charge and spend: write the pattern card?", "One small card, Aion 2 as the source.", "Go."),
    (138, "The productized offer: run step 1?", "Step 1 is a 48-hour niche recon on three candidates.", "Go step 1."),
    (173, "Europatch: lock v1 or ask for v2?", "The patch bay v1 is in the Console, unreviewed.", "Open it, then lock v1."),
    (92, "Style guide: close it?", "Only later folds from BOLO 6 (in storage) are left.", "Close; the folds ride BOLO 6."),
    (105, "Sexology certs: close as researched?", "Recon done 10/5, path and costs written.", "Close as researched."),
    (127, "Workwear: close as researched?", "The first order (about $97) is written up; buying is yours.", "Close as researched."),
    (134, "Expression library: park it?", "The render route has been open since the no-Blender ruling.", "Park it to storage."),
    (123, "The monastic faction: take the name?", "Held until BOLO 100 opens either way.", "The Brethren of the Brink."),
    (106, "The 10/5 follow-ups: still due.", "Detail stays in your private folder.", "You do them this week; say done and I close it."),
    (8, "GitHub purge ticket.", "Only the account owner can file it.", "You file it, about 10 minutes."),
    (9, "Google outdated-content removal.", "Owner action, same family as 8.", "You file it after 8."),
]
LONG = [5, 10, 11, 14, 16, 18, 20, 27, 28, 35, 44, 46, 48, 51, 56, 57, 61, 64, 68, 69, 70, 72, 77, 78, 85, 87, 89,
        90, 93, 96, 97, 100, 101, 102, 107, 108, 109, 113, 118, 121, 129, 130, 131, 132, 133, 135, 136, 146, 147, 152,
        153, 157, 158, 159]
COSMO = sorted(n for n, v in A.items() if v["pick"] == "C")

placed = [n for n, _ in STAMP] + [x[0] for x in DO if x[0]] + [x[0] for x in CALLS] + LONG + COSMO
dupes = sorted({n for n in placed if placed.count(n) > 1})
missing = sorted(set(A) - set(placed))
extra = sorted(set(placed) - set(A))
if dupes or missing or extra:
    sys.exit("coverage: dupes %s · missing %s · not active %s" % (dupes, missing, extra))


def num(n):
    return '<span class="n" title="%s">%s</span>' % (e(A[n]["title"]) if n else "", n if n else "—")


ITEMS = []  # what the page script knows: id, lane, rec text
out = []
out.append("""<title>The Docket</title>
<meta name="claude:viewport-fit-sides" content="cover">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600&display=swap">
<style>
/* layout: one 44px strip with the send bar, a summary row, then lanes ordered by how close to done; every card is a toggle */
:root{
  color-scheme:dark;
  --bg:#050608; --panel:#0a0c0f; --panel2:#10151b; --line:#23272b; --line2:#3a3e40;
  --fg:#c6cbc8; --fg2:#959a97; --dim:#5f6160; --white:#ffffff;
  --acc:#FF5A1F; --acch:#FFB08F; --accsoft:#24110a; --accd:#6e280e;
  --ok:#4ec96f; --oksoft:#0f2416; --am:#e3b341; --amsoft:#2a210b; --cy:#5CC8D0;
  --mono:"IBM Plex Mono",Consolas,monospace; --sans:"IBM Plex Sans","Segoe UI",system-ui,sans-serif;
}
*{box-sizing:border-box}
body{background:var(--bg);color:var(--fg);font:14px/1.5 var(--sans);margin:0}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--panel)}
header{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;min-height:44px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;
  background:var(--panel);border-bottom:1px solid var(--line);padding-block:6px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
header b{font:600 13px var(--mono);letter-spacing:.12em;color:var(--acc)}
header .meta{font:12px var(--mono);color:var(--dim);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
button{font:600 12px var(--mono);letter-spacing:.06em;border:1px solid var(--line2);background:var(--panel2);color:var(--fg);padding:6px 12px;cursor:pointer}
button:hover{border-color:var(--acc)}
button.primary{background:var(--acc);border-color:var(--acc);color:var(--bg)}
button.primary:disabled{background:var(--accd);border-color:var(--accd);color:var(--fg2);cursor:default}
#count{font:600 12px var(--mono);color:var(--white);white-space:nowrap;font-variant-numeric:tabular-nums}
#sent{font:11px var(--mono);color:var(--fg2);flex-basis:100%;min-height:0}
#sent:empty{display:none}
main{max-width:1080px;margin:0 auto;padding-block:20px 48px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:grid;gap:28px}
.sum{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1px;background:var(--line);border:1px solid var(--line)}
.sum a{background:var(--panel);padding:10px 12px;text-decoration:none;color:var(--fg);display:grid;gap:2px}
.sum a:hover,.sum a:focus-visible{background:var(--panel2);outline:none}
.sum em{font:600 24px var(--mono);font-style:normal;color:var(--white);font-variant-numeric:tabular-nums}
.sum small{font:10px var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--fg2)}
.sum .stamp em{color:var(--am)} .sum .do em{color:var(--ok)} .sum .call em{color:var(--acc)}
@media (max-width:700px){.sum{grid-template-columns:repeat(3,minmax(0,1fr))}}
section{display:grid;gap:12px}
h2{margin:0;font:600 12px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--white);display:flex;gap:10px;align-items:baseline;flex-wrap:wrap}
h2 i{font-style:normal;color:var(--dim);letter-spacing:.04em;text-transform:none;font-weight:400}
h2 button{margin-left:auto;font-size:11px;padding:3px 8px}
.lede{margin:0;color:var(--fg2);max-width:70ch;font-size:13px}
.n{display:inline-block;min-width:34px;text-align:center;font:600 12px var(--mono);color:var(--acch);background:var(--accsoft);border:1px solid var(--accd);padding:1px 6px;cursor:help;font-variant-numeric:tabular-nums}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,300px),1fr));gap:10px}
.card{position:relative;background:var(--panel);border:1px solid var(--line);padding:12px 14px 12px 44px;display:grid;gap:6px;align-content:start;min-width:0;cursor:pointer;text-align:left;color:var(--fg);font:inherit;letter-spacing:0}
.card:hover{border-color:var(--line2)}
.card::before{content:"";position:absolute;left:14px;top:14px;width:18px;height:18px;border:1.5px solid var(--line2);background:var(--bg)}
.card[aria-pressed="true"]{border-color:var(--acc);background:var(--accsoft)}
.card[aria-pressed="true"]::before{background:var(--acc);border-color:var(--acc);box-shadow:inset 0 0 0 3px var(--accsoft)}
.card .top{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.card .top b{font:600 13px var(--sans);color:var(--white)}
.card p{margin:0;font-size:13px;color:var(--fg2)}
.rec{display:flex;gap:8px;align-items:baseline;font-size:13px;border-top:1px dashed var(--line2);padding-top:6px;margin-top:2px}
.rec span.k{font:600 10px var(--mono);letter-spacing:.12em;color:var(--bg);padding:1px 5px;flex:none;background:var(--fg2)}
.stamp .rec span.k{background:var(--am)} .do .rec span.k{background:var(--ok)} .call .rec span.k{background:var(--acc)}
.rec em{font-style:normal;color:var(--fg)}
.eta{margin-left:auto;font:11px var(--mono);color:var(--dim);white-space:nowrap}
.note{display:none;margin-top:4px}
.card[aria-pressed="true"] .note{display:block}
.note input{width:100%;font:13px var(--sans);background:var(--bg);color:var(--fg);border:1px solid var(--line2);padding:5px 8px}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{display:inline-flex;gap:6px;align-items:center;font:12px var(--sans);letter-spacing:0;color:var(--fg2);background:var(--panel);border:1px solid var(--line);padding:4px 8px 4px 4px;cursor:pointer}
.chip:hover{border-color:var(--line2);color:var(--fg)}
.chip[aria-pressed="true"]{border-color:var(--cy);color:var(--white);background:#0b1a1c}
details summary{cursor:pointer;font:600 12px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--white)}
details summary i{font-style:normal;color:var(--dim);letter-spacing:.04em;text-transform:none;font-weight:400}
details[open] summary{margin-bottom:12px}
footer{font:11px var(--mono);color:var(--dim);border-top:1px solid var(--line);padding-top:12px}
:focus-visible{outline:2px solid var(--acc);outline-offset:2px}
@media (prefers-reduced-motion:no-preference){.card,.chip{transition:border-color .12s,background .12s}}
</style>
""")
total_open = len(A)
out.append('<header><b>THE DOCKET</b><span class="meta">%d open BOLOs · 11/04 · click what you want done</span>'
           '<span id="count">0 picked</span><button id="gorec" type="button">Go recommended</button>'
           '<button id="clear" type="button">Clear</button><button id="send" class="primary" type="button" disabled>Send to Claude</button>'
           '<span id="sent" role="status"></span></header><main>' % total_open)
out.append('<nav class="sum" aria-label="Lanes">'
           '<a class="stamp" href="#stamp"><em>%d</em><small>Done, stamp it</small></a>'
           '<a class="do" href="#do"><em>%d</em><small>I finish it</small></a>'
           '<a class="call" href="#calls"><em>%d</em><small>Your word</small></a>'
           '<a href="#long"><em>%d</em><small>Long haul</small></a>'
