    else s += ' · waiting on Claude (tell JUDY "docket\u2019s in")';
    $('#sent').textContent = s;
  }

  $('#send').addEventListener('click', async () => {
    if (!db || picked.size === 0) return;
    const picks = [...picked].map(id => {
      const i = byId.get(id), note = (document.getElementById('note-' + id) || {}).value || '';
      return {id, lane: i.lane, act: note.trim() ? 'note' : 'rec', rec: i.rec, note: note.trim()};
    });
    const doc = {picks, sent_at: new Date().toISOString(), done_at: null, done_note: ''};
    const b = $('#send'); b.disabled = true; b.textContent = 'Sending…';
    try {
      await db.doc('orders/latest').set(doc);
      lastSent = doc; showSent(doc); b.textContent = 'Sent';
      setTimeout(() => { b.textContent = 'Send to Claude'; paint(); }, 1500);
    } catch (e) {
      $('#sent').textContent = 'Not sent: ' + ((e && e.message) || 'the store refused the write') + '. Tell me the picks in chat instead.';
      b.textContent = 'Send to Claude'; paint();
    }
  });

  paint();
  (async () => {
    try { db = window.claude && await window.claude.use('db'); } catch (e) { db = null; }
    if (!db) { $('#sent').textContent = 'Sending is off in this view. Tell me the picks in chat.'; paint(); return; }
    paint();
    const timer = setTimeout(() => { if (!lastSent) $('#sent').textContent = 'Can\u2019t reach the store yet; picks still work.'; }, 10000);
    db.doc('orders/latest').onSnapshot(snap => {
      if (!snap.fromCache) clearTimeout(timer);
      const d = snap.exists ? snap.data() : null;
      lastSent = d;
      if (d && !d.done_at && picked.size === 0) { (d.picks || []).forEach(p => { if (byId.has(p.id)) picked.add(p.id);
        const inp = document.getElementById('note-' + p.id); if (inp && p.note) inp.value = p.note; }); paint(); }
      showSent(d);
    }, () => { clearTimeout(timer); });
  })();
})();
</script>""")
io.open(SP + "docket/the-docket.html", "w", encoding="utf-8").write("\n".join(out))
print("ok · stamp %d · do %d · calls %d · long %d · storage %d · total %d" % (len(STAMP), len(DO), len(CALLS), len(LONG), len(COSMO), len(A)))

